mapper.select:
SELECT c.ID, c.PARENT_ID, c.TYPE, c.OBJECT_ID, c.REPLY_COMMENT_ID, c.USER_ID, c.REPLY_USER_ID, c.VISITOR_ID, c.REPLY_VISITOR_ID, c.CONTENT, c.ORIGIN_CONTENT, c.LIKE_COUNT, c.REPLY_COUNT, c.IP_ADDRESS, c.IP_SOURCE, c.USER_AGENT, c.STATUS, c.AUDIT_USER, c.AUDIT_TIME, c.AUDIT_REASON, c.CREATE_TIME, u.NICKNAME AS USER_NICKNAME, u.HEAD_IMG_URL AS USER_AVATAR, v.NICKNAME AS VISITOR_NICKNAME, v.AVATAR AS VISITOR_AVATAR, u2.NICKNAME AS REPLY_USER_NICKNAME, u2.HEAD_IMG_URL AS REPLY_USER_AVATAR, v2.NICKNAME AS REPLY_VISITOR_NICKNAME, v2.AVATAR AS REPLY_VISITOR_AVATAR, IF(c.PARENT_ID = 0, 1, 2) AS LEVEL FROM comment c LEFT JOIN user u ON u.ID = c.USER_ID LEFT JOIN visitor_profile v ON v.VISITOR_ID = c.VISITOR_ID LEFT JOIN user u2 ON u2.ID = c.REPLY_USER_ID LEFT JOIN visitor_profile v2 ON v2.VISITOR_ID = c.REPLY_VISITOR_ID WHERE c.STATUS != 3
AND c.CONTENT LIKE #{contentBind}
AND (u.NICKNAME LIKE #{nicknameBind} OR v.NICKNAME LIKE #{nicknameBind})
AND c.IP_ADDRESS = #{query.ip}
AND c.TYPE = #{query.type}
AND c.PARENT_ID = 0
AND c.PARENT_ID != 0
AND c.STATUS = #{query.status}
AND c.CREATE_TIME >= #{query.createStartTime, jdbcType=TIMESTAMP}
AND c.CREATE_TIME <= #{query.createEndTime, jdbcType=TIMESTAMP}
ORDER BY CREATE_TIME DESC
